use super::prelude::*;

/// `UnsettlingLamp.before_power_amount_changed` — capture phase. On
/// the first eligible debuff application (player → enemy) this combat,
/// flip the relic from `ARMED` to `CAPTURED` so the modify-given arm
/// starts doubling. Per C# canon
/// `UnsettlingLamp.cs::BeforePowerAmountChanged`. Bead `sts2-rs-7uo4`.
pub(crate) fn on_before_power_amount_changed_unsettling_lamp(
    state: &mut CombatState,
    ctx: &crate::hooks::PowerAmountCtx,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::UnsettlingLamp) {
        return EffectResult::NotImplemented;
    }
    if unsettling_lamp_state(state) != Some(UNSETTLING_LAMP_ARMED) {
        return EffectResult::NotImplemented;
    }
    if !unsettling_lamp_eligible(ctx) {
        return EffectResult::NotImplemented;
    }
    // v0.111.0 Models.Relics/UnsettlingLamp.cs: Artifact must not use
    // the once-per-combat trigger when it prevents this application.
    if let crate::hooks::CreatureRef::Enemy(uid) = ctx.target {
        if state
            .creatures
            .iter()
            .find(|c| c.id == uid.0)
            .is_some_and(|c| {
                c.powers.iter().any(|id| {
                    state
                        .powers
                        .get_by_id(id.0)
                        .is_some_and(|p| p.kind == PowerKind::Artifact && p.amount > 0)
                })
            })
        {
            return EffectResult::NotImplemented;
        }
    }
    if let Some(r) = unsettling_lamp_relic_mut(state) {
        r.counter =
            UNSETTLING_LAMP_CAPTURED | ctx.source_card.map_or(0, |uid| (uid.0.get() as i32) << 2);
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

/// `UnsettlingLamp.modify_power_amount_given` — doubling phase. While
/// the relic sits in `CAPTURED`, every eligible debuff applied by the
/// player to an enemy is doubled. Returns `ctx.amount` unchanged when
/// any gate fails (chain-passthrough). Per C# canon
/// `UnsettlingLamp.cs::ModifyPowerAmountGiven`. Bead `sts2-rs-7uo4`.
#[allow(clippy::trivially_copy_pass_by_ref)]
pub(crate) fn on_modify_power_amount_given_unsettling_lamp(
    state: &CombatState,
    ctx: &crate::hooks::PowerAmountCtx,
) -> i32 {
    if !player_owns_relic(state, crate::RelicKind::UnsettlingLamp) {
        return ctx.amount;
    }
    if unsettling_lamp_state(state) != Some(UNSETTLING_LAMP_CAPTURED) {
        return ctx.amount;
    }
    if !unsettling_lamp_eligible(ctx) {
        return ctx.amount;
    }
    let source = state
        .relics
        .iter()
        .find(|r| !r.is_melted && r.kind == crate::RelicKind::UnsettlingLamp)
        .map_or(0, |r| r.counter >> 2);
    if source != 0 && ctx.source_card.map(|uid| uid.0.get() as i32) != Some(source) {
        return ctx.amount;
    }
    ctx.amount.saturating_mul(2)
}

/// `UnsettlingLamp.after_card_played` — finish phase. When the
/// capturing card finishes playing, flip from `CAPTURED` to
/// `FINISHED` so no further doubling happens this combat. Per C#
/// canon `UnsettlingLamp.cs::AfterCardPlayed`. Bead `sts2-rs-7uo4`.
pub(crate) fn on_after_card_played_unsettling_lamp(
    state: &mut CombatState,
    ctx: &CardEventCtx,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::UnsettlingLamp) {
        return EffectResult::NotImplemented;
    }
    if unsettling_lamp_state(state) != Some(UNSETTLING_LAMP_CAPTURED) {
        return EffectResult::NotImplemented;
    }
    if let Some(r) = unsettling_lamp_relic_mut(state) {
        let source = r.counter >> 2;
        if source != 0 && ctx.card_uid.map(|uid| uid.0.get() as i32) != Some(source) {
            return EffectResult::NotImplemented;
        }
        r.counter = UNSETTLING_LAMP_FINISHED;
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

/// `UnsettlingLamp.after_combat_end` — reset to `ARMED` so the next
/// combat re-arms the doubling. Bead `sts2-rs-7uo4`.
pub(crate) fn on_after_combat_end_unsettling_lamp(state: &mut CombatState) -> EffectResult {
    if let Some(r) = unsettling_lamp_relic_mut(state) {
        r.counter = UNSETTLING_LAMP_ARMED;
        EffectResult::Resolved
    } else {
        EffectResult::NotImplemented
    }
}

pub(crate) fn install() {
    register_owned_before_power_amount_changed(
        RelicId::UnsettlingLamp,
        crate::RelicKind::UnsettlingLamp,
        on_before_power_amount_changed_unsettling_lamp as BeforePowerAmountChangedFn,
    );
    register_owned_modify_power_amount_given(
        RelicId::UnsettlingLamp,
        crate::RelicKind::UnsettlingLamp,
        on_modify_power_amount_given_unsettling_lamp as ModifyPowerAmountGivenFn,
    );
    register_after_card_played(
        RelicId::UnsettlingLamp,
        on_after_card_played_unsettling_lamp as AfterCardPlayedFn,
    );
    register_owned_after_combat_end(
        RelicId::UnsettlingLamp,
        crate::RelicKind::UnsettlingLamp,
        on_after_combat_end_unsettling_lamp as AfterCombatEndFn,
    );
}

#[cfg(test)]
mod beta_tests {
    use super::*;

    #[test]
    fn beta_lamp_ignores_artifact_and_nested_card_plays() {
        let mut state = CombatState::default();
        state.init_player_creature();
        let enemy = state.spawn_enemy(crate::MonsterKind::Nibbit);
        state.relics.push(crate::Relic {
            id: std::num::NonZeroU32::new(1).unwrap(),
            kind: crate::RelicKind::UnsettlingLamp,
            counter: 0,
            is_wax: false,
            is_melted: false,
        });
        crate::card_effects::apply_power_to_creature(&mut state, enemy, PowerKind::Artifact, 1);
        let source = crate::CardUid::new(1).unwrap();
        let nested = crate::CardUid::new(2).unwrap();
        let mut ctx = crate::hooks::PowerAmountCtx::new(
            Some(crate::hooks::CreatureRef::Player),
            crate::hooks::CreatureRef::Enemy(enemy),
            PowerKind::Weak,
            2,
        );
        ctx.source_card = Some(source);
        assert_eq!(
            on_before_power_amount_changed_unsettling_lamp(&mut state, &ctx),
            EffectResult::NotImplemented
        );
        assert_eq!(unsettling_lamp_state(&state), Some(UNSETTLING_LAMP_ARMED));
        for power in state
            .powers
            .iter_mut()
            .filter(|p| p.kind == PowerKind::Artifact)
        {
            power.amount = 0;
        }
        assert_eq!(
            on_before_power_amount_changed_unsettling_lamp(&mut state, &ctx),
            EffectResult::Resolved
        );
        assert_eq!(
            on_modify_power_amount_given_unsettling_lamp(&state, &ctx),
            4
        );
        ctx.source_card = Some(nested);
        assert_eq!(
            on_modify_power_amount_given_unsettling_lamp(&state, &ctx),
            2
        );
        let mut played = CardEventCtx {
            card_id: crate::cards::CardId::StrikeNecrobinder,
            card_uid: Some(nested),
            target: None,
            card_tags: crate::cards::CardTags::NONE,
            energy_spent: 0,
            is_autoplay: false,
        };
        assert_eq!(
            on_after_card_played_unsettling_lamp(&mut state, &played),
            EffectResult::NotImplemented
        );
        played.card_uid = Some(source);
        assert_eq!(
            on_after_card_played_unsettling_lamp(&mut state, &played),
            EffectResult::Resolved
        );
        assert_eq!(
            unsettling_lamp_state(&state),
            Some(UNSETTLING_LAMP_FINISHED)
        );
    }
}
